// lead — one USE of the "synth" module.
//
// A node is a `<name>.k7x` in the project's flat `nodes/` folder, and the FILE
// NAMES IT: chains say "lead" (see chains.k7x). It does not sit under the module it uses
// and does not mirror its folders — which module it uses is what `extends` says, and that
// is the only place the relationship is written down.
//
// So state only what THIS voice changes — the 4OSC plugin, the UI and the two automation
// curves all come from the synth module (which in turn extends @workspace/instruments/fourosc).
// The merge order is: fourosc -> synth -> this file, each winning per key.
extends("@workspace/instruments/synth")
params({
  "Filter Freq": 90, // brighter than the shared default — this one has to cut through
})

blobs.bff5ff89181e:
// The lane the "dot" shape module draws on — one shape per layer, so each can be hidden on its
// own and take its own run of effects. No rect: a shape carries its own geometry, so this layer
// covers the whole viewport.
//
// The events name no clip, and that is what they are for here: each is an ACTIVATION, saying WHEN
// the shape is on screen. A lane stating none draws its shapes throughout.
extends("@meta/picture-track")
events([start(2).length(4)])

blobs.c56799858ba3:
// lyrics's channel strip: red, green, blue and transparency.
//
// This is where the lane's level and look are written — its card in the graph, its row in the
// per-track view and the Mixer view are drawings of this one node.
extends("@meta/shaders/video-mixer")

blobs.c9d0ea31a562:
// The drums lane: into the mix, and into `glow`'s audio port — see glow.k7x.
start(true)
steps([
  id("$UUID7").track("drums"),
  to([chain("MIX").level(1), chain("glow").port("audio").level(1)]),
])

blobs.ce998a49c429:
// A SHAPE is a picture source: it starts the chain of the lane it draws on, as a camera would.
// See apps/k7-daw-frontend/packages/song-video/docs/shapes.md.
start(true)
steps([
  id("$UUID12").extends("@workspace/shapes/title"),
  id("$UUID13").track("title_layer"),
])

blobs.d7bc3e22353b:
// The picture lane `main`: its lane item heads its chain, and its shots live in tracks/main,
// a `@meta/picture-track` lane. Its run goes through the `glow` shader on its way to RENDER.
//
// `iris` is a SUBCHAIN that nothing links and that links nowhere: a fade's STRETCH. The second shot
// on main names it (`fadeIn({ over: 1, chain: "iris" })`) and runs through it on its way in.
// See apps/k7-daw-frontend/packages/song-video/docs/transitions.md and apps/k7-daw-wasm/song/docs/chainFiles.md.
start(true)
steps([id("$UUID7").track("main"), to([chain("glow")])])
subchains([
  id("iris").steps([id("$UUID8").extends("@workspace/shaders/iris")]),
])

blobs.dee36a5f7a85:
// imported from cut.otio, track main
extends("@meta/picture-track")
events([ref("counter").start(0).length(4), ref("bars").start(3).length(5).from(1.5).fadeIn(1)])

blobs.eabaaa55ad9a:
// The drums lane: into the mix, and into `glow`'s audio port — see glow.k7x.
start(true)
steps([
  id("$UUID5").track("drums"),
  to([chain("MIX").level(1), chain("glow").port("audio").level(1)]),
])

blobs.ebc74af3ff99:
// The signal graph, as SEGMENTS: each module says where its signal goes next. The chains are
// DERIVED by following the arrows — a run breaks where the signal splits, and where two signals
// meet (which is what a bus is).
//
// The LANES are here too ("melody", "pad"): a lane is a module like any other, and a run is
// named after the lane that starts it. One map, one name space — which is why the pad's synth
// is "synth-pad" rather than sharing its lane's name.
//
// `bypassed` lists the modules the signal passes through untouched, and on a lane — which
// produces rather than passes — that is its mute.

// A lane offers TWO outputs, `audio` and `midi`, and is not typed by what it holds — so the
// key names the one a run leaves by whenever there is anything to say. "melody" holds only
// sequences, so its bare key is unambiguous; "pad" streams from a pattern and holds nothing
// until the transport rolls, so nothing but this line can say its events are notes for the
// synth. See apps/k7-daw-wasm/song/docs/trackModules.md.

// `MIX` is the mixer's sum and `OUT` is the interface; the run between them is the MASTER
// CHAIN, and `OUT` carries the song's output level as its `Volume`. Name a module on that
// line and it processes both lanes together on the way out.

modules({
  melody: ["lead"],
  "pad#midi": ["synth-pad"],
  lead: ["MIX"],
  synth-pad: ["MIX"],
  MIX: ["OUT"],
})

blobs.f993c38c179d:
// A SHAPE is a picture source: it starts the chain of the lane it draws on, as a camera would.
// See apps/k7-daw-frontend/packages/song-video/docs/shapes.md.
start(true)
steps([
  id("$UUID10").extends("@workspace/shapes/title"),
  id("$UUID11").track("title_layer"),
])

blobs.fa0fe1de101f:
// The shader the main lane runs through. Its `audio` port is a SIDE input: the drums lane feeds it
// as well as the mix, and `uAudio` is that lane's live level, so the picture moves with the kit.
ports(["audio"])
steps([
  id("$UUID10").extends("@workspace/shaders/glow"),
  to([chain("RENDER")]),
])

